import os,sys
d=sys.argv[1]
files=sorted(os.listdir(os.path.join(d,"prebuilt")))
libs=[f for f in files if f.endswith(".so")]
bins=[f for f in files if not f.endswith(".so")]
mod=lambda f: "llamacpp_"+f[:-3].replace("+","x") if f.endswith(".so") else f
out=["""// llama.cpp (bslette/llama.cpp volta-nvk) with the Vulkan backend, for NVK on GV11B.
// Prebuilt with the NDK by build-llama-android.sh; the binaries are not in git (see .gitignore).
// Generated by gen-bp.py.
"""]
for f in libs:
    out.append(f"""cc_prebuilt_library_shared {{
    name: "{mod(f)}",
    stem: "{f[:-3]}",
    srcs: ["prebuilt/{f}"],
    system_ext_specific: true,
    compile_multilib: "64",
    check_elf_files: false,
    strip: {{ none: true }},
}}
""")
req=",\n        ".join(f'"{mod(f)}"' for f in libs)
for f in bins:
    out.append(f"""cc_prebuilt_binary {{
    name: "{f}",
    srcs: ["prebuilt/{f}"],
    system_ext_specific: true,
    compile_multilib: "64",
    check_elf_files: false,
    strip: {{ none: true }},
    required: [
        {req},
    ],
}}
""")
open(os.path.join(d,"Android.bp"),"w").write("\n".join(out))
